// Kestrel: combine three REAL HTTP responses. No synthetic traffic values.
const ga4 = $('GA4 Data API').first().json;
const realtime = $('GA4 Realtime API').first().json;
const gsc = $('Search Console API').first().json;
const audit = $input.first().json;
if (!ga4 || typeof ga4 !== 'object' || !gsc || typeof gsc !== 'object') {
  throw new Error('One Google API response is missing');
}
if (!audit || !audit.counts || !Number.isFinite(Number(audit.counts.error))) {
  throw new Error('Unexpected published SEO audit format');
}
const ga4Rows = Array.isArray(ga4.rows) ? ga4.rows : [];
const realtimeRows = Array.isArray(realtime.rows) ? realtime.rows : [];
const activeUsersNow = realtimeRows.reduce((sum, row) => sum + Number(row.metricValues?.[0]?.value ?? 0), 0);
const gscRows = Array.isArray(gsc.rows) ? gsc.rows : [];
const ga4Sessions = ga4Rows.reduce((sum, row) =>
  sum + Number(row.metricValues?.[0]?.value ?? 0), 0);
const ga4Views = ga4Rows.reduce((sum, row) =>
  sum + Number(row.metricValues?.[1]?.value ?? 0), 0);
const gscClicks = gscRows.reduce((sum, row) => sum + Number(row.clicks ?? 0), 0);
const gscImpressions = gscRows.reduce((sum, row) => sum + Number(row.impressions ?? 0), 0);
const errors = Number(audit.counts.error);
const warnings = Number(audit.counts.warning ?? 0);
return [{
  json: {
    project: 'Kestrel SEO Operations Lab',
    data_source: 'Authenticated Google APIs and published Kestrel technical audit',
    ga4_property: '565038230',
    gsc_property: 'https://graceomolola001-cmyk.github.io/kestrel-pseo/',
    ga4_daily_rows: ga4Rows.length,
    ga4_reported_sessions: ga4Sessions,
    ga4_reported_page_views: ga4Views,
    ga4_realtime_active_users: activeUsersNow,
    ga4_realtime_status: realtimeRows.length ? 'Realtime data returned' : 'No active users in current realtime window',
    ga4_status: ga4Rows.length ? 'Report rows returned' : 'No standard report rows yet',
    gsc_page_rows: gscRows.length,
    gsc_returned_clicks: gscClicks,
    gsc_returned_impressions: gscImpressions,
    gsc_status: gscRows.length ? 'Search performance rows returned' : 'No search rows yet (expected for noindex demo)',
    gsc_scope_note: 'GSC returns top page rows; sums are limited to returned rows.',
    audit_pages_checked: Number(audit.pages_checked || 0),
    audit_errors: errors,
    audit_warnings: warnings,
    audit_generated_at: audit.created_at || 'unknown',
    needs_technical_review: errors > 0,
    message: errors > 0
      ? 'Technical errors found. Investigate the reported pages.'
      : 'No critical findings in checked scope. Confirm the audit covered all important pages.',
    data_integrity_note: 'Zero rows are reported as zero rows. No search or session metrics are invented.'
  }
}];
